63	const basePremiumFor = (items: Item[]): number => {
64	  const perItemSum = items.reduce(
65	    (total, item) => total + BASE_PREMIUMS[item.type],
66	    0,
67	  );
68	  const runeCount = items.filter((item) => item.type === "rune").length;
69	  if (runeCount === 3) {
70	    return perItemSum - 3 * BASE_PREMIUMS.rune + 60;
71	  }
72	  return perItemSum;
