const BLOCK_SIZE = 3;
const RUNE_BLOCK_PREMIUM = 60;

const basePremiumFor = (items: Item[]): number => {
  const perItemSum = items.reduce(
    (total, item) => total + BASE_PREMIUMS[item.type],
    0,
  );
  const runeCount = items.filter((item) => item.type === "rune").length;
  if (runeCount === BLOCK_SIZE) {
    return perItemSum - BLOCK_SIZE * BASE_PREMIUMS.rune + RUNE_BLOCK_PREMIUM;
  }
  return perItemSum;
};
